tests/contract/update-workflow.test.ts lines 1-35 of 35

1	/**
2	 * update-workflow.test.ts — the update workflow's permission set, pinned.
3	 *
4	 * `update.on_new_release: pr-agent` makes this run start the agent that resolves the
5	 * pull request a collision stopped it at, and `workflow_dispatch` is the exception a
6	 * `GITHUB_TOKEN` can still make — so `actions: write` is what makes that dispatch
7	 * work. Nothing fails loudly when it goes missing: the run logs a WARN and leaves the
8	 * pull request standing for a person, which is exactly the outcome a repository that
9	 * asked for `pr-agent` did not ask for. That silence is why the set is pinned here
10	 * rather than left to the prose in `src/workflows/atomaton-update.wac.ts`;
11	 * `new-release-notice.test.ts` holds the same pin for the notice's own dispatch.
12	 *
13	 * `checks: write` must stay absent, and it is the key somebody could add innocently:
14	 * it is what would let this job produce a check result of its own, and the checks the
15	 * merge waits behind would stop being the ones the update token's push started.
16	 */
17	import { describe, expect, test } from "bun:test";
18	import { readFileSync } from "node:fs";
19	
20	const WORKFLOW = "dist/.github/workflows/atomaton-update.yml";
21	const document = Bun.YAML.parse(readFileSync(WORKFLOW, "utf8")) as {
22	  permissions?: Record<string, string>;
23	};
24	
25	describe("the update workflow", () => {
26	  test("it holds exactly the permissions its one dispatch needs", () => {
27	    expect(document.permissions).toEqual({
28	      contents: "read",
29	      issues: "write",
30	      "pull-requests": "write",
31	      checks: "read",
32	      actions: "write",
33	    });
34	  });
35	});

